llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a close retinoid analog, has a systemic bioavailability of about 40% at therapeutic oral doses, supporting F ≥ 20% for the retinoid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a structurally related retinoid, has an absolute oral bioavailability of approximately 60% (range 36–95%) after oral dosing, supporting high bioavailability for retinoid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etretinate, a highly lipophilic retinoid ester, has an absolute oral bioavailability of about 44% (range 30–70%), indicating that even poorly soluble retinoids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans retinoic acid oral bioavailability was estimated at 25–30%, still above the 20% threshold and consistent with meaningful oral absorption for retinoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "One qualitative report describes 13-cis retinoic acid as having low and variable absolute bioavailability, but it does not provide a threshold-specific value and is outweighed by quantitative retinoid data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a lipophilic retinoid amide. Although no direct fenretinide bioavailability record is present, the closest retinoid analogs (isotretinoin, acitretin, etretinate, retinoic acid) consistently show oral bioavailability values of about 25–60%, all above the F ≥ 20% threshold. The qualitative low-bioavailability report for one retinoid is not sufficient to overturn the quantitative retinoid evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide is provided.",
    "The effect of the amide and 4-hydroxyphenyl group on first-pass metabolism and absorption relative to retinoic acid/esters is not directly evidenced.",
    "Food/formulation effects on fenretinide bioavailability are not covered by the visible records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

